// shared-pkg @1.0.0 — the nested version uses-old resolves. Same code as 2.0.0,
// but a distinct installed version: the policy pins this one with an fs:read
// deny, so its read is contained even though the bare `shared-pkg` selector is
// granted fs:read.
var fs = require("fs");
module.exports.v = "v1";
module.exports.read = function read(p) {
  try {
    return "READ:" + String(fs.readFileSync(p)).trim();
  } catch (e) {
    return "DENIED";
  }
};
